#include <bits/stdc++.h>
using namespace std;

struct PrimeTable {
    vector<uint32_t> table;
    PrimeTable(uint32_t max_n) {
        table.assign((max_n + 1) / 2, 1);
        table[0] = 0;
        for (uint32_t i = 3;; i += 2) {
            uint64_t i2 = 1ULL * i * i;
            if (i2 > max_n) break;
            if (table[i >> 1] == 1) {
                for (uint32_t j = (uint32_t)i2; j <= max_n; j += i * 2) {
                    if (table[j >> 1] == 1) table[j >> 1] = i;
                }
            }
        }
    }
    bool is_prime(uint32_t n) const {
        return n == 2 || (n % 2 == 1 && table[n >> 1] == 1);
    }
    template <class F>
    void for_each(uint32_t n, F f) const {
        unsigned k = __builtin_ctz(n);
        if (k > 0) f(2, k);
        n >>= k;
        while (n > 1 && table[n >> 1] > 1) {
            uint32_t p = table[n >> 1];
            uint32_t cnt = 1;
            n /= p;
            while (n > 1 && table[n >> 1] == p) {
                n /= p;
                cnt += 1;
            }
            if (n == p) {
                cnt += 1;
                n /= p;
            }
            f(p, cnt);
        }
        if (n > 1) f(n, 1);
    }
    vector<pair<uint32_t, uint32_t>> prime_factors(uint32_t n) const {
        vector<pair<uint32_t, uint32_t>> factors;
        for_each(n, [&](uint32_t p, uint32_t c) { factors.emplace_back(p, c); });
        return factors;
    }
    uint32_t count_divisors(uint32_t n) const {
        uint32_t divisor_cnt = 1;
        for_each(n, [&](uint32_t, uint32_t cnt) { divisor_cnt *= cnt + 1; });
        return divisor_cnt;
    }
};

const uint32_t MOD = 998244353;

struct M {
    uint32_t x;
    M() : x(0) {}
    M(uint64_t v) {
        v %= MOD;
        x = (uint32_t)v;
    }
    static M zero() { return M(0); }
    static M one() { return M(1); }
    static uint32_t mod_add(uint32_t a, uint32_t b) {
        uint32_t c = a + b;
        if (c >= MOD) c -= MOD;
        return c;
    }
    static uint32_t mod_sub(uint32_t a, uint32_t b) {
        if (a < b) return a + MOD - b;
        return a - b;
    }
    static uint32_t mod_mul(uint32_t a, uint32_t b) {
        return (uint64_t)a * b % MOD;
    }
    static uint32_t mod_pow(uint32_t a, uint64_t e) {
        uint32_t r = 1;
        while (e) {
            if (e & 1) r = mod_mul(r, a);
            a = mod_mul(a, a);
            e >>= 1;
        }
        return r;
    }
    static uint32_t mod_inv(uint32_t a) {
        return mod_pow(a, MOD - 2);
    }
    M operator+(const M& o) const { return M(mod_add(x, o.x)); }
    M operator-(const M& o) const { return M(mod_sub(x, o.x)); }
    M operator*(const M& o) const { return M(mod_mul(x, o.x)); }
    M operator/(const M& o) const { return M(mod_mul(x, mod_inv(o.x))); }
    M& operator+=(const M& o) { x = mod_add(x, o.x); return *this; }
    M& operator-=(const M& o) { x = mod_sub(x, o.x); return *this; }
    M& operator*=(const M& o) { x = mod_mul(x, o.x); return *this; }
    M& operator/=(const M& o) { x = mod_mul(x, mod_inv(o.x)); return *this; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    uint32_t n;
    if (!(cin >> n)) return 0;
    PrimeTable pt(n);
    M ans = M::zero();
    M acc = M::zero();
    for (uint32_t i = 1; i <= n; ++i) {
        uint32_t c = pt.count_divisors(i);
        ans = acc + M(c);
        acc += ans;
    }
    cout << ans.x << '\n';
    return 0;
